def poisson_bracket_2d(grad_f_q: list[float], grad_f_p: list[float], grad_g_q: list[float], grad_g_p: list[float]) -> float:
    n = min(len(grad_f_q), len(grad_f_p), len(grad_g_q), len(grad_g_p))
    if n == 0:
        return 0.0
    total = 0.0
    for i in range(n):
        term = float(grad_f_q[i]) * float(grad_g_p[i]) - float(grad_f_p[i]) * float(grad_g_q[i])
        total = total + term
    return total
